using System.Windows.Media;

namespace EDIDReader.App.Controls;

public enum ReIconKind
{
    Home,
    Palette,
    Sun,
    Link,
    Grid,
    Speaker,
    Code,
    Settings,
    Search,
    Refresh,
    Export,
    Display,
    CheckCircle,
    InfoCircle,
    Filter,
    MoreHorizontal,
    Edit,
