public sealed class ReIcon : Control
{
    public static readonly DependencyProperty IconProperty = DependencyProperty.Register(
        nameof(Icon), typeof(ReIconKind), typeof(ReIcon),
        new FrameworkPropertyMetadata(ReIconKind.Home, FrameworkPropertyMetadataOptions.AffectsRender));

    private static readonly IReadOnlyDictionary<ReIconKind, Geometry> Geometries = CreateGeometries();

    static ReIcon()
    {
        DefaultStyleKeyProperty.OverrideMetadata(typeof(ReIcon), new FrameworkPropertyMetadata(typeof(ReIcon)));
        FocusableProperty.OverrideMetadata(typeof(ReIcon), new FrameworkPropertyMetadata(false));
        IsHitTestVisibleProperty.OverrideMetadata(typeof(ReIcon), new FrameworkPropertyMetadata(false));
    }

    public ReIconKind Icon
    {
        get => (ReIconKind)GetValue(IconProperty);
        set => SetValue(IconProperty, value);
    }

    protected override Size MeasureOverride(Size constraint)
    {
        var width = double.IsInfinity(constraint.Width) ? 24 : constraint.Width;
        var height = double.IsInfinity(constraint.Height) ? 24 : constraint.Height;
        return new Size(Math.Min(24, width), Math.Min(24, height));
    }

    protected override void OnRender(DrawingContext drawingContext)
    {
        base.OnRender(drawingContext);

        if (!Geometries.TryGetValue(Icon, out var geometry) || ActualWidth <= 0 || ActualHeight <= 0)
        {
            return;
        }

        var scale = Math.Min(ActualWidth / 24d, ActualHeight / 24d);
        var offsetX = (ActualWidth - 24d * scale) / 2d;
        var offsetY = (ActualHeight - 24d * scale) / 2d;

        drawingContext.PushTransform(new TranslateTransform(offsetX, offsetY));
        drawingContext.PushTransform(new ScaleTransform(scale, scale));
        drawingContext.DrawGeometry(Foreground, null, geometry);
        drawingContext.Pop();
        drawingContext.Pop();
    }

